here = os.path.dirname(os.path.abspath(__file__))
seen = set()
for row in T:
    assert len(row) == 3, row
    assert row[0] not in seen, 'duplicate: ' + row[0]
    seen.add(row[0])
    for t in row[1:]:
        assert sorted(__import__('re').findall(r'\{\d\}', row[0])) == sorted(__import__('re').findall(r'\{\d\}', t)), 'placeholders differ: ' + row[0]
for i, lang in ((1, 'en'), (2, 'zh')):
    with open(os.path.join(here, lang + '.json'), 'w', encoding='utf-8') as f:
        json.dump({r[0]: r[i] for r in T}, f, ensure_ascii=False, indent=0, sort_keys=True)
print(len(T), 'strings')
